for i in range(42):
    for j in range(42):
        if grid[i][j]==2: start=(i,j)
        if grid[i][j]==3: goal=(i,j)

# BFS with parent tracking, count number of shortest paths
def bfs_all(grid,start,goal):
    from collections import deque
    dist={start:0}; parent={start:None}; q=deque([start])
    while q:
        cur=q.popleft()
        i,j=cur
        for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni,nj=i+di,j+dj
