import socket, time

def recv_with_deadline(s, deadline, max_bytes=10000):
    data = b''
    while time.time() < deadline and len(data) < max_bytes:
        remaining = deadline - time.time()
        if remaining <= 0: break
        s.settimeout(remaining)
        try:
            chunk = s.recv(4096)
        except Exception:
            break
        if not chunk: break
        data += chunk
    return data

def parse(data, rows=40, cols=100):
    grid = [[' ']*cols for _ in range(rows)]
    cr, cc = 1, 1
    pos, n = 0, len(data)
    while pos < n:
        b = data[pos]
        if b == 0x1b:
            if pos+1 < n and data[pos+1] == ord('['):
                j = pos+2
                params = ''
                while j < n and not (0x40 <= data[j] <= 0x7e):
                    params += chr(data[j]); j += 1
                if j < n:
                    fin = chr(data[j]); p = params
                    if not p.startswith('?'):
                        if fin in ('H','f'):
                            parts = p.split(';')
                            try:
                                cr = int(parts[0]) if parts[0] else 1
                                cc = int(parts[1]) if len(parts)>1 and parts[1] else 1
                            except: pass
                        elif fin == 'd':
                            try: cr = int(p) if p else 1
                            except: pass
                        elif fin == 'G':
                            try: cc = int(p) if p else 1
                            except: pass
                        elif fin == 'A': cr -= (int(p) if p else 1)
                        elif fin == 'B': cr += (int(p) if p else 1)
                        elif fin == 'C': cc += (int(p) if p else 1)
                        elif fin == 'D': cc -= (int(p) if p else 1)
                    pos = j+1; continue
            else:
                pos += 1; continue
        else:
            if 0x20 <= b <= 0x7e:
                if 1 <= cr <= rows and 1 <= cc <= cols:
                    grid[cr-1][cc-1] = chr(b)
                cc += 1
            pos += 1
    return grid

s = socket.create_connection(('misc.chal.csaw.io', 3535), timeout=10)
t0 = time.time()
banner = recv_with_deadline(s, time.time()+10)
print('BANNER LEN', len(banner), 'T', round(time.time()-t0,1))
s.sendall(b'Level 0 Is Really Easy\n')
time.sleep(0.5)
resp = recv_with_deadline(s, time.time()+5, max_bytes=10000)
print('RESP LEN', len(resp), 'T', round(time.time()-t0,1))
s.close()
open('/tmp/banner2.bin','wb').write(banner)
open('/tmp/resp2.bin','wb').write(resp)
