import socket

def luhn_check(num):
    digits = [int(d) for d in num[::-1]]
    for i in range(1, len(digits), 2):
        digits[i] *= 2
        if digits[i] > 9:
            digits[i] -= 9
    return sum(digits) % 10 == 0

def luhn_gen(prefix, length):
    import random
    while True:
        num = prefix + ''.join(random.choice('0123456789') for _ in range(length - len(prefix)))
        if luhn_check(num):
            return num

