        return luhn_gen('41111111111111', 16)
    elif ctype == 'American Express':
        return luhn_gen('3711111111111', 15)
    elif ctype == 'Discover':
        return luhn_gen('60111111111111', 16)
    else:
        return luhn_gen('510510510510510', 16)

