import string

chars = list(" " + string.ascii_lowercase)

messages = []
with open('messages.txt') as f:
    for line in f:
        line = line.strip()
        if line:
            messages.append(eval(line))

def make_matrix(a, b):
    return [[3, 6, a],
            [b, 4, 2],
            [1, 5, 7]]

def det3(M):
    a,b,c = M[0]; d,e,f = M[1]; g,h,i = M[2]
    return a*(e*i-f*h) - b*(d*i-f*g) + c*(d*h-e*g)

def adj3(M):
    a,b,c = M[0]; d,e,f = M[1]; g,h,i = M[2]
    return [[e*i-f*h, c*h-b*i, b*f-c*e],
            [f*g-d*i, a*i-a*g, c*d-a*f],
            [d*h-e*g, c*g-b*h, a*e-b*d]]

def decrypt_block(M, D, adj, c):
    p = []
    for i in range(3):
        s = sum(adj[i][j]*c[j] for j in range(3))
        if s % D != 0:
            return None
        p.append(s // D)
    return p

candidates = []
for a in range(-30, 60):
    for b in range(-30, 60):
        M = make_matrix(a, b)
        D = det3(M)
        if D == 0:
            continue
        adj = adj3(M)
        all_valid = True
        texts = []
        for msg in messages:
            text = ''
            for i in range(0, len(msg), 3):
                block = msg[i:i+3]
                p = decrypt_block(M, D, adj, block)
                if p is None:
                    all_valid = False
                    break
                for val in p:
                    if not (0 <= val <= 26):
                        all_valid = False
                        break
                    text += chars[val]
                if not all_valid:
                    break
            if not all_valid:
                break
            texts.append(text)
        if all_valid:
            candidates.append((a, b, texts))

print("Number of candidates:", len(candidates))
for a, b, texts in candidates:
    print(f"=== a={a}, b={b} ===")
    for t in texts:
        print(repr(t))
